// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Authorize a collaboration room (server-to-server)
	// (GET /collab/validate)
	ValidateCollabAccess(ctx context.Context, request ValidateCollabAccessRequestObject) (ValidateCollabAccessResponseObject, error)
	// Get the organization's integration config (statuses/kinds, no secrets)
	// (GET /config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// Patch the organization's integration config (per-section, atomic)
	// (PATCH /config)
	UpdateConfig(ctx context.Context, request UpdateConfigRequestObject) (UpdateConfigResponseObject, error)
	// Start App-mode git-provider connect (OAuth-driven)
	// (POST /config/git-provider/connect-sessions)
	StartGitProviderConnect(ctx context.Context, request StartGitProviderConnectRequestObject) (StartGitProviderConnectResponseObject, error)
	// Disconnect the git provider (cascade) for the org
	// (POST /config/git-provider/disconnect)
	DisconnectGitProvider(ctx context.Context, request DisconnectGitProviderRequestObject) (DisconnectGitProviderResponseObject, error)
	// Rotate the IDP publisher client secret (returned once)
	// (POST /config/idp/client-secret)
	RotateIdpClientSecret(ctx context.Context, request RotateIdpClientSecretRequestObject) (RotateIdpClientSecretResponseObject, error)
	// Discover an OIDC issuer's metadata
	// (GET /config/idp/discovery)
	DiscoverIdp(ctx context.Context, request DiscoverIdpRequestObject) (DiscoverIdpResponseObject, error)
	// List the org's external-resource catalog
	// (GET /dependencies/external-resources)
	ListExternalResources(ctx context.Context, request ListExternalResourcesRequestObject) (ListExternalResourcesResponseObject, error)
	// Delete an external-resource catalog entry (409 if in use)
	// (DELETE /dependencies/external-resources/{name})
	DeleteExternalResource(ctx context.Context, request DeleteExternalResourceRequestObject) (DeleteExternalResourceResponseObject, error)
	// List the platform-provisioned resource types available on the cluster
	// (GET /dependencies/platform-resource-types)
	ListPlatformResourceTypes(ctx context.Context, request ListPlatformResourceTypesRequestObject) (ListPlatformResourceTypesResponseObject, error)
	// List organizations
	// (GET /organizations)
	ListOrganizations(ctx context.Context, request ListOrganizationsRequestObject) (ListOrganizationsResponseObject, error)
	// List projects
	// (GET /projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// Create a project
	// (POST /projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// Delete a project
	// (DELETE /projects/{projectName})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// Get a project
	// (GET /projects/{projectName})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// Rehydrate a chat conversation (messages only)
	// (GET /projects/{projectName}/agents/{conversationId}/messages)
	GetConversation(ctx context.Context, request GetConversationRequestObject) (GetConversationResponseObject, error)
	// Start a generation/chat turn (202 — runs detached; attach via the turn stream)
	// (POST /projects/{projectName}/agents/{conversationId}/messages)
	CreateTurn(ctx context.Context, request CreateTurnRequestObject) (CreateTurnResponseObject, error)
	// Trigger a project build
	// (POST /projects/{projectName}/build)
	BuildProject(ctx context.Context, request BuildProjectRequestObject) (BuildProjectResponseObject, error)
	// Compute the build dependency-drawer preflight
	// (GET /projects/{projectName}/build/preflight)
	GetBuildPreflight(ctx context.Context, request GetBuildPreflightRequestObject) (GetBuildPreflightResponseObject, error)
	// Get project build status
	// (GET /projects/{projectName}/build/{tag})
	GetProjectBuild(ctx context.Context, request GetProjectBuildRequestObject) (GetProjectBuildResponseObject, error)
	// List project builds
	// (GET /projects/{projectName}/builds)
	ListProjectBuilds(ctx context.Context, request ListProjectBuildsRequestObject) (ListProjectBuildsResponseObject, error)
	// List components
	// (GET /projects/{projectName}/components)
	ListComponents(ctx context.Context, request ListComponentsRequestObject) (ListComponentsResponseObject, error)
	// Get a component
	// (GET /projects/{projectName}/components/{componentName})
	GetComponent(ctx context.Context, request GetComponentRequestObject) (GetComponentResponseObject, error)
	// List component builds
	// (GET /projects/{projectName}/components/{componentName}/builds)
	ListBuilds(ctx context.Context, request ListBuildsRequestObject) (ListBuildsResponseObject, error)
	// Trigger a component build
	// (POST /projects/{projectName}/components/{componentName}/builds)
	TriggerBuild(ctx context.Context, request TriggerBuildRequestObject) (TriggerBuildResponseObject, error)
	// Get build logs
	// (GET /projects/{projectName}/components/{componentName}/builds/{buildName}/logs)
	GetBuildLogs(ctx context.Context, request GetBuildLogsRequestObject) (GetBuildLogsResponseObject, error)
	// Get component config
	// (GET /projects/{projectName}/components/{componentName}/configs)
	GetComponentConfig(ctx context.Context, request GetComponentConfigRequestObject) (GetComponentConfigResponseObject, error)
	// Update component config
	// (PUT /projects/{projectName}/components/{componentName}/configs)
	UpdateComponentConfig(ctx context.Context, request UpdateComponentConfigRequestObject) (UpdateComponentConfigResponseObject, error)
	// Request access to a cross-project org-service dependency
	// (POST /projects/{projectName}/components/{componentName}/dependencies/{depName}/access-request)
	RequestOrgServiceAccess(ctx context.Context, request RequestOrgServiceAccessRequestObject) (RequestOrgServiceAccessResponseObject, error)
	// Provision a platform-resource dependency (async)
	// (POST /projects/{projectName}/components/{componentName}/dependencies/{depName}/provision)
	ProvisionPlatformResource(ctx context.Context, request ProvisionPlatformResourceRequestObject) (ProvisionPlatformResourceResponseObject, error)
	// Get a dependency's provisioning status (outputs masked to names)
	// (GET /projects/{projectName}/components/{componentName}/dependencies/{depName}/status)
	GetDependencyStatus(ctx context.Context, request GetDependencyStatusRequestObject) (GetDependencyStatusResponseObject, error)
	// List component deployments
	// (GET /projects/{projectName}/components/{componentName}/deployments)
	ListDeployments(ctx context.Context, request ListDeploymentsRequestObject) (ListDeploymentsResponseObject, error)
	// Get a component's OpenAPI spec
	// (GET /projects/{projectName}/components/{componentName}/openapi)
	GetComponentOpenapi(ctx context.Context, request GetComponentOpenapiRequestObject) (GetComponentOpenapiResponseObject, error)
	// List a consumer project's access requests
	// (GET /projects/{projectName}/dependencies/access-requests)
	ListAccessRequests(ctx context.Context, request ListAccessRequestsRequestObject) (ListAccessRequestsResponseObject, error)
	// Collect an external dependency's values and provision it
	// (POST /projects/{projectName}/dependencies/external-resources/{name}/values)
	CollectExternalResourceValues(ctx context.Context, request CollectExternalResourceValuesRequestObject) (CollectExternalResourceValuesResponseObject, error)
	// List spec files at HEAD
	// (GET /projects/{projectName}/files)
	ListFiles(ctx context.Context, request ListFilesRequestObject) (ListFilesResponseObject, error)
	// Atomically apply a batch of writes/deletes (single commit to main)
	// (POST /projects/{projectName}/files/apply)
	ApplyFiles(ctx context.Context, request ApplyFilesRequestObject) (ApplyFilesResponseObject, error)
	// Read a spec file at HEAD
	// (GET /projects/{projectName}/files/{path})
	ReadFile(ctx context.Context, request ReadFileRequestObject) (ReadFileResponseObject, error)
	// List/search GitHub issues on a project's repo
	// (GET /projects/{projectName}/issues)
	ListIssues(ctx context.Context, request ListIssuesRequestObject) (ListIssuesResponseObject, error)
	// Create a GitHub issue on a project's repo
	// (POST /projects/{projectName}/issues)
	CreateIssue(ctx context.Context, request CreateIssueRequestObject) (CreateIssueResponseObject, error)
	// Get the collaboration session descriptor for the spec workspace
	// (GET /projects/{projectName}/spec/collab-session)
	GetSpecCollabSession(ctx context.Context, request GetSpecCollabSessionRequestObject) (GetSpecCollabSessionResponseObject, error)
	// Get a project's SDLC status
	// (GET /projects/{projectName}/status)
	GetProjectStatus(ctx context.Context, request GetProjectStatusRequestObject) (GetProjectStatusResponseObject, error)
	// List spec version tags
	// (GET /projects/{projectName}/tags)
	ListProjectTags(ctx context.Context, request ListProjectTagsRequestObject) (ListProjectTagsResponseObject, error)
	// List a project's Tasks (live GitHub ⋈ executions → derived status), optionally scoped to one spec/build version tag
	// (GET /projects/{projectName}/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// Get one Task with its full Execution history
	// (GET /projects/{projectName}/tasks/{issueNumber})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// Stream a Task's live state (status + executions + unified timeline) as SSE
	// (GET /projects/{projectName}/tasks/{issueNumber}/log)
	StreamTaskLog(ctx context.Context, request StreamTaskLogRequestObject) (StreamTaskLogResponseObject, error)
	// Turn an ad-hoc GitHub issue into a coding Task and dispatch it (async)
	// (POST /projects/{projectName}/tasks/{issueNumber}/promote-from-issue)
	PromoteTaskFromIssue(ctx context.Context, request PromoteTaskFromIssueRequestObject) (PromoteTaskFromIssueResponseObject, error)
	// Get the project's running turn (204 when none)
	// (GET /projects/{projectName}/turns/active)
	GetActiveTurn(ctx context.Context, request GetActiveTurnRequestObject) (GetActiveTurnResponseObject, error)
	// Get one turn's status
	// (GET /projects/{projectName}/turns/{turnId})
	GetTurn(ctx context.Context, request GetTurnRequestObject) (GetTurnResponseObject, error)
	// Attach to a turn's event stream (SSE replay + live tail)
	// (GET /projects/{projectName}/turns/{turnId}/stream)
	StreamTurn(ctx context.Context, request StreamTurnRequestObject) (StreamTurnResponseObject, error)
	// List RCA-agent alert reports across the caller's org, newest first
	// (GET /rca-agent/reports)
	ListRcaAgentReports(ctx context.Context, request ListRcaAgentReportsRequestObject) (ListRcaAgentReportsResponseObject, error)
	// Record a new RCA-agent alert report (internal/service-authenticated writer; issue
	// (POST /rca-agent/reports)
	CreateRcaAgentReport(ctx context.Context, request CreateRcaAgentReportRequestObject) (CreateRcaAgentReportResponseObject, error)
	// Get a single RCA-agent alert report
	// (GET /rca-agent/reports/{reportId})
	GetRcaAgentReport(ctx context.Context, request GetRcaAgentReportRequestObject) (GetRcaAgentReportResponseObject, error)
	// List skills
	// (GET /skills)
	ListSkills(ctx context.Context, request ListSkillsRequestObject) (ListSkillsResponseObject, error)
	// Create a custom skill
	// (POST /skills)
	CreateSkill(ctx context.Context, request CreateSkillRequestObject) (CreateSkillResponseObject, error)
	// Import an AgentSkills tarball
	// (POST /skills/import)
	ImportSkill(ctx context.Context, request ImportSkillRequestObject) (ImportSkillResponseObject, error)
	// Sync built-in skills (creates the org's skills repo if missing)
	// (POST /skills/sync)
	SyncSkills(ctx context.Context, request SyncSkillsRequestObject) (SyncSkillsResponseObject, error)
	// List available built-in skill updates
	// (GET /skills/updates)
	ListSkillUpdates(ctx context.Context, request ListSkillUpdatesRequestObject) (ListSkillUpdatesResponseObject, error)
	// Delete a custom or imported skill
	// (DELETE /skills/{name})
	DeleteSkill(ctx context.Context, request DeleteSkillRequestObject) (DeleteSkillResponseObject, error)
	// Get a skill
	// (GET /skills/{name})
	GetSkill(ctx context.Context, request GetSkillRequestObject) (GetSkillResponseObject, error)
	// Update a custom skill
	// (PUT /skills/{name})
	UpdateSkill(ctx context.Context, request UpdateSkillRequestObject) (UpdateSkillResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ValidateCollabAccess operation middleware
func (sh *strictHandler) ValidateCollabAccess(w http.ResponseWriter, r *http.Request, params ValidateCollabAccessParams) {
	var request ValidateCollabAccessRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ValidateCollabAccess(ctx, request.(ValidateCollabAccessRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ValidateCollabAccess")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ValidateCollabAccessResponseObject); ok {
		if err := validResponse.VisitValidateCollabAccessResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

